function assertDisplayableOmissionDataset(data) {
const hasProvenance = typeof data.source === "string" && data.source.length > 0
&& typeof data.methodology === "string" && data.methodology.length > 0
&& typeof data.verified === "boolean"
&& typeof data.mock === "boolean";
if (!hasProvenance || (!data.mock && !data.verified)) {
throw new Error("Omission data requires source, methodology, verified, and mock provenance.");
}
}
function updateOmissions() {
const pbmKey = document.getElementById("pbm-selector").value;
const data = pbmData[pbmKey];
assertDisplayableOmissionDataset(data);
document.getElementById("estimated-gap").innerText = data.gap;
document.getElementById("gap-provenance").innerText = data.mock
? "Synthetic fixture; not an estimate about a real company"
: `Source label: ${data.source} | Methodology: ${data.methodology}`;
const container = document.getElementById("omission-grid-container");
container.replaceChildren();
data.quarters.forEach(item => {
const isRecorded = item.status === "recorded";
const statusClass = isRecorded ? "recorded" : "omitted";
const card = document.createElement("div");
card.className = `omission-card ${statusClass}`;
const quarter = document.createElement("div");
quarter.className = "quarter-label";
quarter.textContent = item.q;
const badge = document.createElement("span");
badge.className = `status-badge ${statusClass}`;
badge.textContent = item.status;
const amount = document.createElement("div");
amount.className = "amount-display";
amount.style.color = isRecorded ? "var(--accent-green-text)" : "var(--accent-red-text)";
amount.textContent = item.amount;
const desc = document.createElement("div");
desc.className = "omission-desc";
desc.style.color = isRecorded ? "var(--text-muted)" : "var(--accent-red-text)";
desc.textContent = item.desc;
card.append(quarter, badge, amount, desc);
container.appendChild(card);
});
}
updateOmissions();
window.projects = [
{ id: 0, title: "Co-op Pharmacy Solar Grid", votes: 120 },
{ id: 1, title: "Free Insulin Dispensary", votes: 195 },
{ id: 2, title: "Zero-Emission Micro-Logistics", votes: 64 }
];
const TOTAL_MATCHING_POOL = 84250;
window.castVote = function(projectId) {
const proj = window.projects.find(p => p.id === projectId);
if (proj) {
proj.votes += 1;
window.recalculateMatching();
}
};
window.recalculateMatching = function() {
let totalWeight = 0;
const weights = window.projects.map(p => {
const sq = p.votes * p.votes;
totalWeight += sq;
return sq;
});
const poolAmount = window.TOTAL_MATCHING_POOL !== undefined ? window.TOTAL_MATCHING_POOL : TOTAL_MATCHING_POOL;
window.projects.forEach((p, idx) => {
const share = weights[idx] / totalWeight;
const matchingAmount = Math.round(share * poolAmount);
document.getElementById(`proj-${p.id}-votes`).innerText = `${p.votes} votes`;
document.getElementById(`proj-${p.id}-match`).innerText = `$${matchingAmount.toLocaleString()}`;
});
};
window.recalculateMatching();
let secondsLeft = 18 * 24 * 60 * 60 + 6 * 60 * 60 + 12 * 60 + 45;
setInterval(() => {
secondsLeft -= 1;
if (secondsLeft < 0) secondsLeft = 0;
const d = Math.floor(secondsLeft / (24 * 60 * 60));
const h = Math.floor((secondsLeft % (24 * 60 * 60)) / (60 * 60));
const m = Math.floor((secondsLeft % (60 * 60)) / 60);
const s = secondsLeft % 60;
const pad = (num) => String(num).padStart(2, '0');
document.getElementById("rollover-countdown").innerText =
`${d}d ${pad(h)}h ${pad(m)}m ${pad(s)}s`;
}, 1000);
function merkleLeafJS(pharmacyAddress, amount, eligibleCap) {
const inner = ethers.solidityPackedKeccak256(
["address", "uint256", "uint256"],
[pharmacyAddress, amount, eligibleCap]
);
return ethers.keccak256(ethers.solidityPacked(["bytes32"], [inner]));
}
function processProofJS(proof, leaf) {
let computedHash = leaf;
for (const proofElement of proof) {
if (!ethers.isHexString(proofElement, 32)) {
throw new Error(`Invalid proof element: ${proofElement}`);
}
const pair = [computedHash, proofElement].sort();
computedHash = ethers.keccak256(ethers.solidityPacked(["bytes32", "bytes32"], pair));
}
return computedHash;
}
function verifyMerkleProofJS(proof, root, leaf) {
return processProofJS(proof, leaf).toLowerCase() === root.toLowerCase();
}
document.getElementById("btn-verify-portability").addEventListener("click", () => {
const allowPartial = document.getElementById("checkbox-allow-partial").checked;
const allowIncomplete = document.getElementById("checkbox-allow-incomplete").checked;
const statusEl = document.getElementById("portability-verification-status");
const resultsEl = document.getElementById("portability-verification-results");
const listEl = document.getElementById("portability-results-list");
const titleEl = document.getElementById("portability-results-title");
statusEl.className = "";
statusEl.style.color = "var(--text-muted)";
statusEl.innerText = "Verifying...";
resultsEl.style.display = "none";
listEl.replaceChildren();
const jsonText = document.getElementById("portability-json-input").value.trim();
if (!jsonText) {
statusEl.style.color = "var(--accent-red-text)";
statusEl.innerText = "Error: Input is empty.";
return;
}
let payload;
try {
payload = JSON.parse(jsonText);
} catch (err) {
statusEl.style.color = "var(--accent-red-text)";
statusEl.innerText = "Error: Invalid JSON format.";
return;
}
const errors = [];
const warnings = [];
if (!payload || typeof payload !== "object") {
errors.push("Payload must be a JSON object.");
} else {
let exporter;
try {
exporter = ethers.getAddress(payload.exporter);
} catch {
errors.push("Missing or invalid exporter address.");
}
if (!payload.exported_at || Number.isNaN(Date.parse(payload.exported_at))) {
errors.push("Missing or invalid exported_at timestamp.");
}
for (const field of ["claims", "merkle_proofs", "votes", "receipts"]) {
if (!Array.isArray(payload[field])) {
errors.push(`${field} must be an array.`);
}
}
if (payload.schema_version === undefined) {
errors.push("Completeness field schema_version is missing.");
} else {
if (payload.schema_version !== "1.1.0") {
errors.push("Unsupported schema_version; expected 1.1.0.");
}
if (payload.is_partial === undefined) {
errors.push("Completeness field is_partial is missing.");
} else if (typeof payload.is_partial !== "boolean") {
errors.push("is_partial must be a boolean.");
}
if (payload.warnings === undefined) {
errors.push("Completeness field warnings is missing.");
} else if (!Array.isArray(payload.warnings)) {
errors.push("warnings must be an array.");
} else if (payload.warnings.some((warning) => typeof warning !== "string")) {
errors.push("warnings entries must be strings.");
}
}
if (payload.is_partial === false && Array.isArray(payload.warnings) && payload.warnings.length > 0) {
errors.push("A complete export cannot contain partial-export warnings.");
}
if (payload.is_partial === true) {
if (allowPartial) {
if (Array.isArray(payload.warnings)) {
for (const w of payload.warnings) {
warnings.push(`[Partial Export Warning] ${w}`);
}
} else {
warnings.push("Export is marked as partial.");
}
} else {
errors.push("Export is marked as partial (contains query failures). Check 'Allow Partial RPC Data' to override.");
if (Array.isArray(payload.warnings)) {
for (const w of payload.warnings) {
errors.push(`[Partial Export Error] ${w}`);
}
}
}
}
if (errors.length === 0) {
const receiptsByHash = new Map();
for (const receipt of payload.receipts) {
if (!receipt.hash || !ethers.isHexString(receipt.hash, 32)) {
errors.push(`Receipt has invalid hash: ${receipt.hash}`);
continue;
}
receiptsByHash.set(receipt.hash.toLowerCase(), receipt);
}
for (const claim of payload.claims) {
let pharmacy;
try {
pharmacy = ethers.getAddress(claim.pharmacyAddress);
} catch {
errors.push(`Claim ${claim.claimId || "(unknown)"} has invalid pharmacyAddress.`);
continue;
}
if (pharmacy !== exporter) {
errors.push(`Claim ${claim.claimId || "(unknown)"} pharmacyAddress does not match exporter.`);
}
if (!receiptsByHash.has(String(claim.transactionHash || "").toLowerCase())) {
errors.push(`Claim ${claim.claimId || "(unknown)"} is missing a matching receipt.`);
}
if (claim.metadataProvenance !== "synthetic-placeholder" && claim.ndc === "unavailable-off-chain") {
errors.push(`Claim ${claim.claimId || "(unknown)"} has unavailable clinical metadata without synthetic provenance.`);
}
}
for (const proof of payload.merkle_proofs) {
if (!ethers.isHexString(proof.claimRoot, 32)) {
errors.push(`Merkle proof at index ${proof.leafIndex} has invalid claimRoot.`);
continue;
}
try {
const pharmacy = ethers.getAddress(proof.pharmacy);
if (pharmacy !== exporter) {
errors.push(`Merkle proof at index ${proof.leafIndex} pharmacy does not match exporter.`);
}
const leaf = merkleLeafJS(pharmacy, BigInt(proof.grossAmount), BigInt(proof.eligibleCap));
const proofItems = Array.isArray(proof.proof) ? proof.proof : [];
const valid = verifyMerkleProofJS(proofItems, proof.claimRoot, leaf);
if (!valid) {
errors.push(`Merkle proof at index ${proof.leafIndex} does not verify against claimRoot.`);
}
} catch (err) {
errors.push(`Merkle proof at index ${proof.leafIndex} is malformed: ${err.message}`);
}
}
for (const vote of payload.votes) {
try {
const voter = ethers.getAddress(vote.voter);
if (voter !== exporter) {
errors.push(`Vote for project ${vote.project || "(unknown)"} voter does not match exporter.`);
}
} catch {
errors.push(`Vote for project ${vote.project || "(unknown)"} has invalid voter address.`);
}
}
if (payload.merkle_proofs.length === 0 && payload.claims.length > 0) {
if (allowIncomplete) {
warnings.push("Claims exist without Merkle proof material; export is not independently claim-verifiable.");
} else {
errors.push("Claims exist without Merkle proof material; export is not independently claim-verifiable. Check 'Allow Incomplete Merkle Proofs' to override.");
}
}
}
}
warnings.push("Offline prototype: checks untrusted export self-consistency only. Authoritative chain provenance requires verify-export.js with --rpc and confirmed roots.");
resultsEl.style.display = "block";
if (errors.length === 0) {
if (payload.is_partial === true) {
statusEl.style.color = "var(--accent-orange)";
statusEl.innerText = "Warning partial accepted with override";
titleEl.innerText = "Verification Success (Partial Override)";
titleEl.style.color = "var(--accent-orange)";
} else {
statusEl.style.color = "var(--accent-green-text)";
statusEl.innerText = "Local Structural Check Passed";
titleEl.innerText = "Local Check Passed";
titleEl.style.color = "var(--accent-green-text)";
}
const li = document.createElement("li");
li.style.color = "var(--text-main)";
li.innerText = "OK: JSON structure complies with schema.";
listEl.appendChild(li);
const li2 = document.createElement("li");
li2.style.color = "var(--text-main)";
li2.innerText = "Merkle proofs are internally consistent with the claimRoot supplied by this payload.";
listEl.appendChild(li2);
} else {
statusEl.style.color = "var(--accent-red-text)";
statusEl.innerText = "Verification Failed";
titleEl.innerText = "Verification Errors";
titleEl.style.color = "var(--accent-red-text)";
errors.forEach(err => {
const li = document.createElement("li");
li.style.color = "var(--accent-red-text)";
li.innerText = `- ${err}`;
listEl.appendChild(li);
});
}
warnings.forEach(warn => {
const li = document.createElement("li");
li.style.color = "var(--accent-orange)";
li.innerText = `Warning: ${warn}`;
listEl.appendChild(li);
});
});
